def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[8] * cols for _ in range(rows)]

    background = 8

    # Fill pattern cycled every 3 rows
    def get_fill_pattern(offset, fill_color, width=6):
        if offset % 3 == 0:
            return [fill_color] * width
        elif offset % 3 == 1:
            return [background] + [fill_color] * (width - 1)
        else:
            return [fill_color] + [background] + [fill_color]

    # Determine fill colors from pattern rows
    fill_colors = {
        'top': 1,   # rows 2-4 have 1s
        'bottom': 3 # rows 19-21 have 3s
    }

    # Apply transformations for TOP-LEFT (cols 3-8)
    for r in range(rows):
        if 2 <= r <= 4:
            # Pattern rows 2-4: copy from original
            for col_offset in range(3, 9):
                if col_offset < len(grid[r]):
                    result[r][col_offset] = grid[r][col_offset]
        elif 5 <= r <= 11:
            # Fill rows 5-11: apply fill pattern (7 fill rows)
            fill_color = 1
            fill_pattern = get_fill_pattern(r - 4, fill_color)  # offset from row 5-1
            for c_idx in range(6):
                if 3 + c_idx < len(result[r]):
                    result[r][3 + c_idx] = fill_pattern[c_idx]

    # Apply transformations for TOP-RIGHT (cols 13-18) - rows 4-11
    for r in range(4, 13):
        # Check if already filled
        if r <= 11:
            for col_offset in range(13, 19):
                if col_offset < len(grid[r]):
                    result[r][col_offset] = grid[r][col_offset]

    # Apply transformations for BOTTOM-LEFT (cols 3-8), rows 19-25
    for r in range(19, 26):
        if 19 <= r <= 21:
            # Pattern rows 19-21: copy from original
            for col_offset in range(3, 9):
                if col_offset < len(grid[r]):
                    result[r][col_offset] = grid[r][col_offset]
        elif 22 <= r <= 25:
            # Fill rows 22-25: apply fill pattern
            fill_color = 3
            fill_pattern = get_fill_pattern(r - 18, fill_color)  # offset from row 5-1
            for c_idx in range(6):
                if 3 + c_idx < len(result[r]):
                    result[r][3 + c_idx] = fill_pattern[c_idx]

    return result

